update pages set contenu = '{"sections":[]}'::jsonb where path = '/travaux-industriels/transfert-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Transfert industriel et déménagement de machines industrielles","mecanisme":"**Votre outil de production redémarre à la date prévue.** Pas trois semaines après, pas en mode dégradé.","cta":"Faire chiffrer mon transfert","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · techniciens salariés Migen, pas de chaîne d''intermédiaires."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et des hubs techniques en France."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."}]},{"type":"probleme","punchline":"Ce que coûte l''improvisation, dans l''ordre où ça arrive","puces":[{"accroche":"Équipement endommagé au levage","texte":", parce que les points d''élingage n''ont pas été relevés avant la dépose."},{"accroche":"Câblage et tuyauterie raccordés à la hâte","texte":", sans repérage : la panne apparaît trois jours après le redémarrage."},{"accroche":"Programmes perdus.","texte":"Personne n''a sauvegardé l''automate avant la coupure, et le dernier qui connaissait la recette est parti l''an dernier."},{"accroche":"Chaîne qui repart en retard.","texte":"Vos clients, eux, ne décalent pas leurs commandes."}]}]'::jsonb) where path = '/travaux-industriels/transfert-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"texte":"**Audit de faisabilité et plan d''implantation**"},"benefice":"Vous savez avant de signer ce qui passe, ce qui ne passe pas, et où chaque machine se pose sur le site d''arrivée."},{"prestation":{"texte":"**Pilotage complet du projet**"},"benefice":"Un chef de projet, un numéro, un compte rendu. Vous arbitrez sur votre production, plus entre trois prestataires."},{"prestation":{"texte":"**Déménagement de machines industrielles**"},"benefice":"Une machine ou un parc entier déplacés par des techniciens qui savent ce qu''ils démontent, et pourquoi."},{"prestation":{"texte":"**Transfert de ligne de production**"},"benefice":"Des lignes complètes phasées pour que vos livraisons ne s''arrêtent pas pendant le chantier."},{"prestation":{"texte":"**[Levage et manutention lourde](/travaux-industriels/levage-manutention/)**"},"benefice":"Chaque charge déplacée selon un mode opératoire écrit, avec les moyens dimensionnés pour elle."},{"prestation":{"texte":"**[Démantèlement industriel](/travaux-industriels/demantelement-industriel/) du site de départ**"},"benefice":"L''ancien site rendu libre et propre, avec la traçabilité des déchets. Vous rendez les clés sans réserve."},{"prestation":{"texte":"**[Montage industriel](/travaux-industriels/montage-industriel/) sur le site d''arrivée**"},"benefice":"Les équipements neufs du nouveau site montés par la même équipe que celle qui remonte les anciens."},{"prestation":{"texte":"**Travaux de maintenance à l''occasion de la dépose**"},"benefice":"La machine part révisée plutôt qu''usée. Vous gagnez une remise à niveau sans second arrêt."}],"prose":[{"texte":"Les deux termes désignent la même opération : sortir un outil de production d''un site et le remettre en marche ailleurs."},{"texte":"Nous employons le second, parce que la question qui compte n''est pas « quand la machine arrive » mais « quand elle produit ». Un déménagement d''usine réussi se mesure au premier bon produit sorti, pas au dernier carton livré."},{"texte":"Un transfert d''usine complet ajoute trois contraintes que le déplacement d''une machine isolée n''a pas."},{"texte":"C''est pour cela qu''un déménagement d''usine se pilote comme un projet, avec un plan d''implantation validé et un phasage écrit, jamais comme une succession de prestations achetées séparément."},{"texte":"Une ligne ne se coupe pas en deux sans conséquence. Le transfert de ligne de production se prépare autour d''une seule question : que produit-on pendant le chantier ?"},{"texte":"Trois réponses possibles, choisies avec vous au moment de l''audit."}]}]'::jsonb) where path = '/travaux-industriels/transfert-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Audit et faisabilité.","texte":"Visite du site de départ et du site d''arrivée, inventaire des équipements, contraintes d''accès, contraintes de sécurité. La faisabilité est validée avec votre responsable de production."},{"titre":"Plan d''implantation et planning.","texte":"Place de chaque machine, circulation des matières, réseaux et énergies. Le phasage est calé sur vos dates de livraison, pas sur les nôtres."},{"titre":"Préparation du site d''arrivée.","texte":"Massifs, scellements, alimentations, réseaux fluides. Tout ce qui peut se faire pendant que l''ancien site produit encore se fait maintenant."},{"titre":"Démontage et conditionnement.","texte":"Consignation, sauvegarde des programmes, repérage du câblage et des tuyauteries, dépose, calage. Chaque repère servira au remontage."},{"titre":"Transport et logistique.","texte":"Moyens de levage dimensionnés, transporteurs spécialisés quand le gabarit l''exige, autorisations gérées par nous."},{"titre":"Remontage et raccordements.","texte":"Mise à niveau, calage, raccordement mécanique, électrique, automatisme, hydraulique, pneumatique, tuyauterie."},{"titre":"Essais et remise en service.","texte":"Essais à vide, essais sous production, réglages, contrôle qualité, accompagnement de la montée en cadence."},{"titre":"Dossier de fin de chantier.","texte":"Plans d''implantation à jour, repérages, comptes rendus, réserves levées. Votre équipe de maintenance récupère un site documenté."}]},{"type":"garanties","puces":[{"accroche":"Le planning validé ensemble est l''outil de pilotage.","texte":"Chaque écart est signalé sans attendre, expliqué et traité avec vous. Pas de découverte en réunion de fin de chantier."},{"accroche":"La sécurité passe avant le calendrier.","texte":"Analyse de risque, plan de prévention, modes opératoires écrits pour chaque phase de levage, pour vos équipes comme pour les nôtres."},{"accroche":"Tout ce qui peut se préparer sans arrêter la production l''est.","texte":"Le site d''arrivée est prêt avant que la première machine bouge. C''est ce qui raccourcit l''arrêt réel."},{"accroche":"Celui qui démonte est celui qui remonte.","texte":"La même équipe suit la machine de bout en bout. C''est la seule façon de ne pas perdre en route ce qui n''a pas été écrit."}]},{"type":"cta","question":"Besoin de savoir ce que coûterait le transfert de votre site ?","bouton":"Faire chiffrer mon transfert","href":"/contact/","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/travaux-industriels/transfert-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Montage et déplacement de machines, étanchéité et isolation, 2025.","texte":"Délais de chantier tenus sans pénalité, transferts de machines sécurisés, sans casse ni improvisation","lienLibelle":"Étude de cas SOPREMA","lienHref":"/preuves/soprema/"},{"titre":"Montage d''un centre logistique, Clermont-Ferrand, 2023.","texte":"12 monteurs mécaniciens et 8 engins de levage mobilisés en pleine période estivale, site livré à la date prévue","lienLibelle":"Étude de cas AKTID","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Construction d''un site de R&D bas carbone, région parisienne.","texte":"Chantier piloté de bout en bout par Orthus, filiale du groupe, coordination multi-métiers et jalons critiques suivis","lienLibelle":"Étude de cas ORTHUS x ECOCEM","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Montage de portiques de lavage, partout en France.","texte":"Réception, assemblage, levage, raccordements mécaniques et électriques, validation à l''issue du montage","lienLibelle":"Étude de cas ORTHUS x WASHTEC","lienHref":"/preuves/orthus-washtec/"},{"titre":"Contrôle de chantier sur des projets stratégiques, 2025 à 2026.","texte":"Phases critiques sécurisées, qualité des installations maintenue, aucun recrutement d''urgence côté client","lienLibelle":"Étude de cas ALSTEF Group","lienHref":"/preuves/alstef-group/"}]}]'::jsonb) where path = '/travaux-industriels/transfert-industriel/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Combien coûte un transfert industriel ?","reponse":"Le montant dépend du nombre d''équipements, des contraintes d''accès, de la distance et du niveau de prestation retenu. Le chiffrage est établi sur devis après audit, gratuitement, poste par poste. Un prix annoncé sans visite est un prix qui bougera."},{"question":"Quelle différence entre transfert industriel et déménagement industriel ?","reponse":"Aucune sur le fond : les deux désignent le déplacement d''un outil de production. Le mot transfert met l''accent sur la remise en service, le mot déménagement sur le transport. Une entreprise de transfert industriel doit savoir faire les deux, sinon elle laisse la moitié du chantier à quelqu''un d''autre."},{"question":"Peut-on transférer une usine sans arrêter la production ?","reponse":"Rarement en totalité, mais l''arrêt se réduit fortement par le phasage : transfert par tronçons, stock d''avance, site d''arrivée préparé, équipements critiques basculés en dernier. C''est l''objet du plan de transfert."},{"question":"Comment choisir une entreprise de transfert industriel ?","reponse":"Trois questions suffisent à trier. Qui remonte et rebranche, vos équipes ou les siennes ? Qui signe le planning et répond des écarts ? Qui vous rend un dossier de fin de chantier exploitable ? Si l''une des trois réponses est « un sous-traitant », c''est vous qui arbitrerez le jour du chantier."},{"question":"Déplacez-vous une seule machine ou uniquement des sites complets ?","reponse":"Les deux. Le déménagement de machines industrielles à l''unité relève du même métier : consignation, repérage, dépose, levage, calage, remontage, essais. La différence est l''échelle du phasage, pas la nature du geste."},{"question":"Qui est responsable en cas de casse pendant le transfert ?","reponse":"Le sujet est traité avant le chantier. Le devis et le cahier des charges précisent les responsabilités de chaque partie, les garanties et l''assurance mobilisée. Vous savez qui répond de quoi avant le premier câble débranché."},{"question":"Qui sont les techniciens qui interviennent ?","reponse":"Des salariés Migen, évalués en entretien technique et en entretien comportemental. Seuls 10 % des candidats sont retenus, et les résultats d''évaluation sont partagés avec vous. Mécanique, électricité, électromécanique, automatisme, hydraulique, pneumatique, soudure et chaudronnerie, robotique."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui, depuis 4 agences : Lyon (siège), Montréal, Dubaï, Madrid, avec des hubs techniques sur le territoire. Le hub de techniciens proche du site de départ et celui proche du site d''arrivée travaillent sur le même dossier, avec un seul interlocuteur."}]},{"type":"ctaFinal","question":"Besoin d''un premier avis sur votre transfert, même s''il n''est prévu que dans six mois ?","bouton":"Parler à un chargé d''affaires","href":"/contact/","rappel":"04 78 33 72 05, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/travaux-industriels/transfert-industriel/';
